$('align').onclick=()=>{let f=items.find(f=>f.id===selected);if(!f)return;let candidates=[];for(const w of wallRects()){for(const sign of[-1,1]){const a=w.rot*Math.PI/180;let nx=Math.sin(a)*sign,nz=Math.cos(a)*sign;let along=(f.x-w.x)*Math.cos(a)-(f.z-w.z)*Math.sin(a);along=Math.max(-w.w/2+f.w/2,Math.min(w.w/2-f.w/2,along));let n={...f,rot:w.rot+(sign<0?180:0),x:w.x+Math.cos(a)*along+nx*(f.d/2+w.d/2),z:w.z-Math.sin(a)*along+nz*(f.d/2+w.d/2)};if(sameRoom(f,n)&&!issues(n,items).length)candidates.push({n,dist:Math.hypot(n.x-f.x,n.z-f.z)});}}candidates.sort((a,b)=>a.dist-b.dist);if(candidates[0]){commitFurniture(f,candidates[0].n);notify('已移到最近可用牆面；遇到家具會先停住。')}else notify('找不到足夠寬的可用牆面。');};
